use std::{env,fs,io::{self,Write}};use spore_core::{creature_skin_sse_field_v1::{evaluate,SnapshotAdmission},creature_generated_skin_kernel_v1::Lane,creature_generated_skin_grid_query_v1::CELL_COUNT,native_sse::Policy};
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),2);let b=fs::read(&a[1]).unwrap();assert_eq!(b.len(),1220);let v:Vec<u32>=b.chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();let mut out=Vec::new();for c in v.chunks_exact(61){let n=c[4] as usize;assert!(n<=2);let mut records=Vec::new();for r in 0..n {let lanes=std::array::from_fn(|i|{let x=5+(r*4+i)*7;Lane{center:[f32::from_bits(c[x]),f32::from_bits(c[x+1]),f32::from_bits(c[x+2])],cutoff:f32::from_bits(c[x+3]),scale:f32::from_bits(c[x+4]),coefficient:f32::from_bits(c[x+5]),key:c[x+6]}});records.push(lanes);}let mut cells:[Option<&[[Lane;4]]>;CELL_COUNT]=[None;CELL_COUNT];if n>0{cells[0]=Some(&records);}let point=[f32::from_bits(c[0]),f32::from_bits(c[1]),f32::from_bits(c[2])];let v=evaluate(point,[0.;3],[1.;3],f32::from_bits(c[3]^0x80000000),&cells,Policy::Mxcsr1f80,SnapshotAdmission).unwrap();out.extend(v.value.to_bits().to_le_bytes());}io::stdout().write_all(&out).unwrap();}
